// Some shipped E3 VCDs refer to transitions missing even from the original
// beta Alyx model. Use the authored destination posture and retain the VCD's
// event ramp/crossfade. Exact matches always win, including newer model sets.
static int GammaLookupSceneSequence( CBaseFlex *pActor, const char *pName )
{
    int sequence=pActor->LookupSequence(pName);
    if (sequence>=0 || Q_stricmp(STRING(pActor->GetModelName()),"models/alyx.mdl"))
        return sequence;
    struct Alias_t { const char *missing; const char *posture; };
    static const Alias_t aliases[] = {
        {"pos01_pos03_tran","posture03"},
        {"post05_post06","posture06"},
        {"post06_post05","posture05"},
        {"pos05_pos07","posture07"},
    };
    for (int i=0;i<ARRAYSIZE(aliases);++i)
    {
        if (Q_stricmp(pName,aliases[i].missing)) continue;
        sequence=pActor->LookupSequence(aliases[i].posture);
        if (sequence>=0)
            DevMsg("Gamma scene: beta Alyx transition %s uses authored destination %s\n",pName,aliases[i].posture);
        return sequence;
    }
    return -1;
}

